recipes.code:
{
  "inputs": [
    {
      "id": "vynix-api-token",
      "type": "promptString",
      "description": "Personal access token generated at https://www.vynix.in/mcp.",
      "password": true
    }
  ],
  "servers": {
    "vynix": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@usevynix/mcp-server@0.1.4"
      ],
      "env": {
        "VYNIX_API_URL": "https://www.vynix.in",
        "VYNIX_API_TOKEN": "${input:vynix-api-token}"
      }
    }
  }
}
